('a0000000-0000-4000-8000-000000000003', 'reading', 'sentence_completion', 9, 3, 'Neuroscientists use the term ______________ to describe the process by which the brain compresses a series of actions into a single retrievable unit.', NULL, NULL, 'chunking', 'sentence_completion'),
